56	static int http_get(const char *path, char *out, int outlen)
57	{
58	    struct hostent *he;
59	    struct sockaddr_in sa;
60	    int fd, n, total = 0;
61	    char req[256];
62	
63	    he = gethostbyname(DM_W_HOST);
64	    if (he == NULL)
65	        return -1;
66	
67	    fd = socket(AF_INET, SOCK_STREAM, 0);
68	    if (fd < 0)
69	        return -1;
70	
71	    memset(&sa, 0, sizeof(sa));
72	    sa.sin_family = AF_INET;
73	    sa.sin_port   = htons(DM_W_PORT);
74	    memcpy(&sa.sin_addr, he->h_addr, he->h_length);
75	
76	    if (connect(fd, (struct sockaddr *)&sa, sizeof(sa)) < 0)
77	        {
78	            close(fd);
79	            return -1;
80	        }
81	
82	    snprintf(req, sizeof(req),
83	             "GET %s HTTP/1.1\r\n"
84	             "Host: %s\r\n"
85	             "Connection: close\r\n"
86	             "\r\n",
87	             path, DM_W_HOST);
88	
89	    if (send(fd, req, strlen(req), 0) < 0)
90	        {
91	            close(fd);
92	            return -1;
93	        }
94	
95	    while (total < outlen - 1)
96	        {
97	            n = recv(fd, out + total, outlen - 1 - total, 0);
98	            if (n <= 0)
99	                break;
100	            total += n;
101	        }
102	
103	    close(fd);
104	    out[total] = '\0';
105	
106	    /* Skip HTTP header */
107	    char *body = strstr(out, "\r\n\r\n");
108	    if (body != NULL)
109	        {
110	            body += 4;
111	            memmove(out, body, strlen(body) + 1);
112	        }
113	
114	    return (strlen(out) > 0) ? 0 : -1;
115	}
