599	    if (!sensor_sub.initialized) {
600	        LV_LOG_WARN("Sensor subscriptions not initialized");
601	        return -1;
602	    }
603	    /* 只poll有效的文件描述符 */
604	    int valid_fd_count = 0;
605	    for (int i = 0; i < LV_DEMO_POLLFD_NUM; i++) {
606	        if (sensor_sub.fds[i].fd != -1) {
607	            valid_fd_count++;
608	        }
609	    }
610	    if (valid_fd_count == 0) {
611	        LV_LOG_WARN("No valid sensor file descriptors available");
612	        return 0;
613	    }
614	    int ret = poll(sensor_sub.fds, LV_DEMO_POLLFD_NUM, 100);
615	    if (ret < 0) {
616	        LV_LOG_ERROR("Failed to poll sensor data: %d", ret);
617	        return -1;
618	    }
619	    if (ret == 0) {
620	        /* 没有可读数据是正常的，不是错误 */
621	        return 0;
622	    }
623	    int updated = 0;
624	    /* 更新温度数据 */
625	    if ((sensors_to_update & LV_DEMO_UPDATE_TEMPERATURE) &&
626	        (sensor_sub.temperature_sub >= 0) &&
627	        (sensor_sub.fds[0].revents & POLLIN)) {
628	        struct sensor_temp temp_data;
