632	            LV_LOG_INFO("Temperature updated: %.1f°C", temp_data.temperature);
633	            updated++;
634	        } else {
635	            LV_LOG_WARN("Failed to copy temperature data");
636	        }
637	    }
638	    /* 更新湿度数据 */
639	    if ((sensors_to_update & LV_DEMO_UPDATE_HUMIDITY) &&
640	        (sensor_sub.humidity_sub >= 0) &&
641	        (sensor_sub.fds[1].revents & POLLIN)) {
642	        struct sensor_humi humi_data;
643	        if (orb_copy(ORB_ID(sensor_humi), sensor_sub.humidity_sub, &humi_data) == OK) {
644	            /* 直接更新全局湿度主题 */
645	            lv_subject_set_int(&humidity_subject, (int)(humi_data.humidity * 10));
646	            LV_LOG_INFO("Humidity updated: %.1f%%", humi_data.humidity);
647	            updated++;
648	        } else {
649	            LV_LOG_WARN("Failed to copy humidity data");
650	        }
651	    }
652	    /* 修改距离传感器数据处理部分 */
653	    if ((sensors_to_update & LV_DEMO_UPDATE_PROX) &&
654	        (sensor_sub.prox_sub >= 0) &&
655	        (sensor_sub.fds[2].revents & POLLIN)) {
656	        uint8_t raw_data[32];
657	        memset(raw_data, 0, sizeof(raw_data));
658	
659	        if (orb_copy(ORB_ID(sensor_prox), sensor_sub.prox_sub, raw_data) == OK) {
660	            float distance_cm = 0.0f;
661	
662	            float *float_ptr = (float*)(raw_data + 8);
663	            float distance_m = *float_ptr;
664	            distance_cm = distance_m * 100.0f;
665	            LV_LOG_INFO("Raw distance: %.3f m = %.1f cm", distance_m, distance_cm);
666	            /* 只确保最小值不为负，去掉最大值限制 */
667	            if (distance_cm < 0) {
668	                distance_cm = 0;
669	                LV_LOG_WARN("Distance < 0, clamped to 0 cm");
670	            }
671	            lv_subject_set_int(&prox_subject, (int)(distance_cm * 10));
672	            LV_LOG_INFO("Proximity updated: %.1f cm", distance_cm);
673	            updated++;
674	        }
675	    }
676	    //syslog(LOG_DEBUG, "Sensors updated: %d", updated);
677	    return updated;
