213	/* ================================================================
214	 * Weekday from "YYYY-MM-DD" (Zeller) → 0=Sun..6=Sat
215	 * ================================================================ */
216	
217	static int weekday_from_date(const char *date)
218	{
219	    int y, m, d;
220	    if (sscanf(date, "%d-%d-%d", &y, &m, &d) != 3)
221	        return -1;
222	    if (m < 3)
223	        {
224	            m += 12;
225	            y--;
226	        }
227	    /* Zeller: h = (q + 13(m+1)/5 + K + K/4 + J/4 + 5J) % 7, 0=Sat */
228	    int h = (d + (13 * (m + 1)) / 5 + (y % 100) + (y % 100) / 4
229	             + (y / 100) / 4 + 5 * (y / 100)) % 7;
230	    return (h + 6) % 7;     /* shift 0=Sat → 0=Sun */
231	}
