int dm_weather_fetch(dm_weather_t *w)
{
    static char buf[4096];
    char dates[DM_WEATHER_DAYS][16];
    int codes[DM_WEATHER_DAYS]  = {0};
    int tmax[DM_WEATHER_DAYS]   = {0};
    int tmin[DM_WEATHER_DAYS]   = {0};
    int n, i;
    struct timeval t0, t1;

    if (w == NULL)
        return -1;

    memset(w, 0, sizeof(*w));

    /* 2026-08-10：记录耗时供 debug 显示 */
    gettimeofday(&t0, NULL);

    if (http_get(DM_W_PATH, buf, sizeof(buf)) < 0)
        {
            dm_fill_fake(w);
            gettimeofday(&t1, NULL);
            dbg_set("FAIL %ldms: %s",
                    (long)((t1.tv_sec - t0.tv_sec) * 1000 +
                           (t1.tv_usec - t0.tv_usec) / 1000),
                    g_dbg);   /* 保留 http_get 写的具体失败原因 */
            return -1;   /* 2026-08-10：失败返回 -1，UI 据此缩短重试周期 */
        }

    /* Current weather */
    if (strstr(buf, "\"current\":") != NULL)
        {
            json_int(buf, "\"temperature_2m\"", &w->cur_temp);
            json_int(buf, "\"relative_humidity_2m\"", &w->cur_humid);
            json_int(buf, "\"weather_code\"", &w->cur_code);
        }

    /* Daily forecast */
    n = json_str_array(buf, "\"time\"", dates, DM_WEATHER_DAYS);
    if (n == 0)
        {
            dm_fill_fake(w);
            gettimeofday(&t1, NULL);
            dbg_set("FAIL %ldms: parse (no time[] in JSON)",
                    (long)((t1.tv_sec - t0.tv_sec) * 1000 +
                           (t1.tv_usec - t0.tv_usec) / 1000));
            return -1;   /* 2026-08-10：解析失败同样返回 -1 触发快速重试 */
        }

    json_int_array(buf, "\"weather_code\"", codes, DM_WEATHER_DAYS);
    json_int_array(buf, "\"temperature_2m_max\"", tmax, DM_WEATHER_DAYS);
    json_int_array(buf, "\"temperature_2m_min\"", tmin, DM_WEATHER_DAYS);

    w->n_days = n;
    for (i = 0; i < n; i++)
        {
            strncpy(w->days[i].date, dates[i], sizeof(w->days[i].date) - 1);
            w->days[i].date[sizeof(w->days[i].date) - 1] = '\0';
            w->days[i].code  = codes[i];
            w->days[i].tmax  = tmax[i];
            w->days[i].tmin  = tmin[i];
            w->days[i].wday  = weekday_from_date(dates[i]);
        }

    gettimeofday(&t1, NULL);
    dbg_set("OK %ldms: %s, %d days, %dC/%d%%",
            (long)((t1.tv_sec - t0.tv_sec) * 1000 +
                   (t1.tv_usec - t0.tv_usec) / 1000),
            DM_W_LAT, w->n_days, w->cur_temp, w->cur_humid);
    return 0;
}

/* 2026-08-10：返回最近一次 fetch 的 debug 字符串（worker 线程写） */
const char *dm_weather_debug(void)
{
    return g_dbg;
}

