254	static int weekday_from_date(const char *date)
255	{
256	    int y, m, d;
257	    if (sscanf(date, "%d-%d-%d", &y, &m, &d) != 3)
258	        return -1;
259	    if (m < 3)
260	        {
261	            m += 12;
262	            y--;
263	        }
264	    /* Zeller: h = (q + 13(m+1)/5 + K + K/4 + J/4 + 5J) % 7, 0=Sat */
265	    int h = (d + (13 * (m + 1)) / 5 + (y % 100) + (y % 100) / 4
266	             + (y / 100) / 4 + 5 * (y / 100)) % 7;
267	    return (h + 6) % 7;     /* shift 0=Sat → 0=Sun */
268	}
