/* 本地复刻板端 dm_weather.c 的完整解析流程（原样复制逻辑） */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define DM_WEATHER_DAYS 5

/* --- 原样复制 dm_weather.c 的三个解析函数 --- */
static int json_int(const char *json, const char *key, int *val)
{
    const char *p = strstr(json, key);
    if (p == NULL) return -1;
    p = strchr(p, ':');
    if (p == NULL) return -1;
    p++;
    while (*p == ' ' || *p == '\t') p++;
    *val = atoi(p);
    return 0;
}

static int json_int_array(const char *json, const char *key, int *out, int max)
{
    const char *p = strstr(json, key);
    int n = 0;
    if (p == NULL) return 0;
    p = strchr(p, '[');
    if (p == NULL) return 0;
    p++;
    while (n < max)
    {
        while (*p == ' ' || *p == '\t' || *p == ',') p++;
        if (*p == ']' || *p == '\0') break;
        out[n++] = atoi(p);
        while (*p >= '0' && *p <= '9') p++;
        if (*p == '.') { p++; while (*p >= '0' && *p <= '9') p++; }
        if (*p == '-') p++;
    }
    return n;
}

static int json_str_array(const char *json, const char *key, char out[][16], int max)
{
    const char *p = strstr(json, key);
    int n = 0;
    if (p == NULL) return 0;
    p = strchr(p, '[');
    if (p == NULL) return 0;
    p++;
    while (n < max)
    {
        const char *q = strchr(p, '"');
        if (q == NULL) break;
        q++;
        const char *e = strchr(q, '"');
        if (e == NULL) break;
        size_t len = e - q;
        if (len > 15) len = 15;
        memcpy(out[n], q, len);
        out[n][len] = '\0';
        n++;
        p = e + 1;
    }
    return n;
}

int main(void)
{
    FILE *f = fopen("weather_resp.json", "r");
    char buf[4096];
    size_t len = fread(buf, 1, sizeof(buf) - 1, f);
    buf[len] = '\0';
    fclose(f);

    char dates[DM_WEATHER_DAYS][16];
    int codes[DM_WEATHER_DAYS] = {0}, tmax[DM_WEATHER_DAYS] = {0}, tmin[DM_WEATHER_DAYS] = {0};
    int cur_temp = -999, cur_humid = -999, cur_code = -999, n;

    printf("=== 板端 dm_weather.c 原逻辑在真实响应上的提取结果 ===\n");
    if (strstr(buf, "\"current\":") != NULL)
    {
        json_int(buf, "\"temperature_2m\"", &cur_temp);
        json_int(buf, "\"relative_humidity_2m\"", &cur_humid);
        json_int(buf, "\"weather_code\"", &cur_code);
    }
    printf("cur_temp=%d  cur_humid=%d  cur_code=%d\n", cur_temp, cur_humid, cur_code);

    n = json_str_array(buf, "\"time\"", dates, DM_WEATHER_DAYS);
    json_int_array(buf, "\"weather_code\"", codes, DM_WEATHER_DAYS);
    json_int_array(buf, "\"temperature_2m_max\"", tmax, DM_WEATHER_DAYS);
