/* 验证修复后逻辑：从 "current": / "daily": 段内解析 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define DM_WEATHER_DAYS 5

static int json_int(const char *json, const char *key, int *val)
{
    const char *p = strstr(json, key);
    if (p == NULL) return -1;
    p = strchr(p, ':');
    if (p == NULL) return -1;
    p++;
    while (*p == ' ' || *p == '\t') p++;
    *val = atoi(p);
    return 0;
}
static int json_int_array(const char *json, const char *key, int *out, int max)
{
    const char *p = strstr(json, key);
    int n = 0;
    if (p == NULL) return 0;
    p = strchr(p, '[');
    if (p == NULL) return 0;
    p++;
    while (n < max)
    {
        while (*p == ' ' || *p == '\t' || *p == ',') p++;
        if (*p == ']' || *p == '\0') break;
        out[n++] = atoi(p);
        while (*p >= '0' && *p <= '9') p++;
        if (*p == '.') { p++; while (*p >= '0' && *p <= '9') p++; }
        if (*p == '-') p++;
    }
    return n;
}
static int json_str_array(const char *json, const char *key, char out[][16], int max)
{
    const char *p = strstr(json, key);
    int n = 0;
    if (p == NULL) return 0;
    p = strchr(p, '[');
    if (p == NULL) return 0;
    p++;
    while (n < max)
    {
        const char *q = strchr(p, '"');
        if (q == NULL) break;
        q++;
        const char *e = strchr(q, '"');
        if (e == NULL) break;
        size_t len = e - q;
        if (len > 15) len = 15;
        memcpy(out[n], q, len);
        out[n][len] = '\0';
        n++;
        p = e + 1;
    }
    return n;
}

int main(void)
{
    FILE *f = fopen("weather_resp.json", "r");
    char buf[4096];
    size_t len = fread(buf, 1, sizeof(buf) - 1, f);
    buf[len] = '\0';
    fclose(f);

    char dates[DM_WEATHER_DAYS][16];
    int codes[5]={0}, tmax[5]={0}, tmin[5]={0};
    int cur_temp=-999, cur_humid=-999, cur_code=-999, n=0;

    const char *cur = strstr(buf, "\"current\":");
    if (cur != NULL)
    {
        json_int(cur, "\"temperature_2m\"", &cur_temp);
        json_int(cur, "\"relative_humidity_2m\"", &cur_humid);
        json_int(cur, "\"weather_code\"", &cur_code);
    }
    const char *dl = strstr(buf, "\"daily\":");
    if (dl != NULL)
    {
        n = json_str_array(dl, "\"time\"", dates, DM_WEATHER_DAYS);
        json_int_array(dl, "\"weather_code\"", codes, DM_WEATHER_DAYS);
        json_int_array(dl, "\"temperature_2m_max\"", tmax, DM_WEATHER_DAYS);
        json_int_array(dl, "\"temperature_2m_min\"", tmin, DM_WEATHER_DAYS);
    }

    printf("=== 修复后提取结果 ===\n");
    printf("cur_temp=%d  cur_humid=%d  cur_code=%d\n", cur_temp, cur_humid, cur_code);
    printf("n_days=%d\n", n);
    for (int i = 0; i < n; i++)
        printf("  day%d: %s code=%d tmax=%d tmin=%d\n", i, dates[i], codes[i], tmax[i], tmin[i]);
    printf("\n期望: cur 28/79/1; days: 10..14\n");
    return 0;
}
EOF
