/* 模拟修复后的 http_get：req[512] + 完整请求头 + 5s 超时 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <netinet/in.h>
#include <netdb.h>

#define DM_W_LAT "23.11"
#define DM_W_LON "114.42"
#define DM_W_TZ  "Asia%2FShanghai"
#define DM_W_HOST "api.open-meteo.com"
#define DM_W_PORT 80
#define DM_W_PATH \
    "/v1/forecast?latitude=" DM_W_LAT "&longitude=" DM_W_LON \
    "&current=temperature_2m,relative_humidity_2m,weather_code" \
    "&daily=weather_code,temperature_2m_max,temperature_2m_min" \
    "&timezone=" DM_W_TZ "&forecast_days=5"

int main(void)
{
    struct hostent *he = gethostbyname(DM_W_HOST);
    if (!he) { printf("DNS fail\n"); return 1; }
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    struct timeval tv = {5, 0};
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
    struct sockaddr_in sa;
    memset(&sa, 0, sizeof(sa));
    sa.sin_family = AF_INET;
    sa.sin_port = htons(DM_W_PORT);
    memcpy(&sa.sin_addr, he->h_addr, he->h_length);
    if (connect(fd, (struct sockaddr *)&sa, sizeof(sa)) < 0) { printf("connect fail (%d)\n", errno); return 1; }

    char req[512];
    int reqlen = snprintf(req, sizeof(req),
        "GET %s HTTP/1.1\r\nHost: %s\r\nConnection: close\r\n\r\n",
        DM_W_PATH, DM_W_HOST);
    printf("reqlen=%d (旧 256 会截断, 现 512 完整)\n", reqlen);
    if (reqlen >= (int)sizeof(req)) { printf("req truncated\n"); return 1; }
    if (send(fd, req, reqlen, 0) < 0) { printf("send fail (%d)\n", errno); return 1; }

    char out[4096]; int total = 0, n;
    while (total < (int)sizeof(out) - 1) {
        n = recv(fd, out + total, sizeof(out) - 1 - total, 0);
        if (n <= 0) break;
        total += n;
    }
    close(fd);
    out[total] = '\0';
    char *body = strstr(out, "\r\n\r\n");
    if (body) { body += 4; memmove(out, body, strlen(body) + 1); }
    printf("recv total=%d bytes, body head: %.120s\n", total, out);
    printf("含 temperature_2m: %s\n", strstr(out, "temperature_2m") ? "YES" : "NO");
    return 0;
}
